#include <bits/stdc++.h>
using namespace std;

struct node{
    int a, b, c;
};

void sol(){
    int n;
    cin>>n;
    vector<node> a(n + 5);
    vector<int> b(n + 5);
    for(int i = 1;i <= n;i++)
        cin>>a[i].a>>a[i].b>>a[i].c;
    long long res = 0;
    int cnt1 = 0, cnt2 = 0, cnt3 = 0;
    for(int i = 1;i <= n;i++){
        if(a[i].a >= max(a[i].b, a[i].c))
            b[i] = 1, res += a[i].a, cnt1++;
        else if(a[i].b >= max(a[i].a, a[i].c))
            b[i] = 2, res += a[i].b, cnt2++;
        else
            b[i] = 3, res += a[i].c, cnt3++;
    }
    vector<int> ans;
    for(int i = 1;i <= n;i++){
        if(cnt1 > n/2 && b[i] == 1)
            ans.push_back(a[i].a - max(a[i].b, a[i].c));
        else if(cnt2 > n/2 && b[i] == 2)
            ans.push_back(a[i].b - max(a[i].a, a[i].c));
        else if(cnt3 > n/2 && b[i] == 3)
            ans.push_back(a[i].c - max(a[i].a, a[i].b));
    }
    sort(ans.begin(), ans.end());
    int i = 0;
    while(cnt1 > n/2)
        res -= ans[i++], cnt1--;
    while(cnt2 > n/2)
        res -= ans[i++], cnt2--;
    while(cnt3 > n/2)
        res -= ans[i++], cnt3--;
    cout<<res<<'\n';
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    while(t--)
        sol();
}

#include <bits/stdc++.h>
using namespace std;
#define cs(x) isp(x.top().second); ist(x.top().second); sel[x.top().second] = 1; x.pop();
#define ct(x) its(x.top().second); itp(x.top().second); sel[x.top().second] = 2; x.pop();
#define cp(x) ips(x.top().second); ipt(x.top().second); sel[x.top().second] = 3; x.pop();
#define ips(x) ps.push({-::p[x] + ::s[x], x})
#define isp(x) sp.push({-::s[x] + ::p[x], x})
#define ipt(x) pt.push({-::p[x] + ::t[x], x})
#define itp(x) tp.push({-::t[x] + ::p[x], x})
#define ist(x) st.push({-::s[x] + ::t[x], x})
#define its(x) ts.push({-::t[x] + ::s[x], x})

int n, s[100005], t[100005], p[100005], sel[100005];
void solve() {
	cin >> n;
	priority_queue<pair<int,int>> s1, s2, s3, sp, ps, st, ts, pt, tp;

	memset(sel, 0, sizeof(sel));
	for (int i = 1; i <= n; ++i) {
		cin >> s[i] >> t[i] >> p[i];
		s1.push({s[i], i});
		s2.push({t[i], i});
		s3.push({p[i], i});
	}
	int p = n/2, s = n/2, t = n/2;
	int ans = 0;
	while (1) {
		int mxw = 0, typ = -1;
		while (!s1.empty() && sel[s1.top().second] != 0) s1.pop();
		while (!s2.empty() && sel[s2.top().second] != 0) s2.pop();
		while (!s3.empty() && sel[s3.top().second] != 0) s3.pop();
		while (!sp.empty() && sel[sp.top().second] != 1) sp.pop();
		while (!st.empty() && sel[st.top().second] != 1) st.pop();
		while (!tp.empty() && sel[tp.top().second] != 2) tp.pop();
		while (!ts.empty() && sel[ts.top().second] != 2) ts.pop();
		while (!ps.empty() && sel[ps.top().second] != 3) ps.pop();
		while (!pt.empty() && sel[pt.top().second] != 3) pt.pop();
		if (!s1.empty()) {
			auto to = s1.top();
			if (s && to.first > mxw) {
				mxw = to.first;
				typ = 0;
			}
			if (t && !st.empty() && to.first + st.top().first > mxw) {
				mxw = to.first + st.top().first;
				typ = 1;
			}
			if (p && !sp.empty() && to.first + sp.top().first > mxw) {
				mxw = to.first + sp.top().first;
				typ = 2;
			}
			if (t && !sp.empty() && !pt.empty() && to.first + pt.top().first + sp.top().first > mxw) {
				mxw = to.first + pt.top().first + sp.top().first;
				typ = 3;
			}
			if (p && !st.empty() && !tp.empty() && to.first + st.top().first + tp.top().first > mxw) {
				mxw = to.first + st.top().first + tp.top().first;
				typ = 4;
			}
		}
		if (!s2.empty()) {
			auto to = s2.top();
			if (t && to.first > mxw) {
				mxw = to.first;
				typ = 5;
			}
			if (s && !ts.empty() && to.first + ts.top().first > mxw) {
				mxw = to.first + ts.top().first;
				typ = 6;
			}
			if (p && !tp.empty() && to.first + tp.top().first > mxw) {
				mxw = to.first + tp.top().first;
				typ = 7;
			}
			if (s && !tp.empty() && !ps.empty() && to.first + tp.top().first + ps.top().first > mxw) {
				mxw = to.first + tp.top().first + ps.top().first;
				typ = 8;
			}
			if (p && !ts.empty() && !sp.empty() && to.first + ts.top().first + sp.top().first > mxw) {
				mxw = to.first + ts.top().first + sp.top().first;
				typ = 9;
			}
		}
		if (!s3.empty()) {
			auto to = s3.top();
			if (p && to.first > mxw) {
				mxw = to.first;
				typ = 10;
			}
			if (s && !ps.empty() && to.first + ps.top().first > mxw) {
				mxw = to.first + ps.top().first;
				typ = 11;
			}
			if (t && !pt.empty() && to.first + pt.top().first > mxw) {
				mxw = to.first + pt.top().first;
				typ = 12;
			}
			if (s && !pt.empty() && !ts.empty() && to.first + pt.top().first + ts.top().first > mxw) {
				mxw = to.first + pt.top().first + ts.top().first;
				typ = 13;
			}
			if (t && !ps.empty() && !st.empty() && to.first + ps.top().first + st.top().first > mxw) {
				mxw = to.first + ps.top().first + st.top().first;
				typ = 14;
			}
		}
		if (typ == -1) break;
		ans += mxw;
		if (typ == 0) { --s; cs(s1); }
		else if (typ == 1) { --t; cs(s1); ct(st); }
		else if (typ == 2) { --p; cs(s1); cp(sp); }
		else if (typ == 3) { --t; cs(s1); cp(sp); ct(pt); }
		else if (typ == 4) { --p; cs(s1); ct(st); cp(tp); }
		else if (typ == 5) { --t; ct(s2); }
		else if (typ == 6) { --s; ct(s2); cs(ts); }
		else if (typ == 7) { --p; ct(s2); cp(tp); }
		else if (typ == 8) { --s; ct(s2); cp(tp); cs(ps); }
		else if (typ == 9) { --p; ct(s2); cs(ts); cp(sp); }
		else if (typ == 10) { --p; cp(s3); }
		else if (typ == 11) { --s; cp(s3); cs(ps); }
		else if (typ == 12) { --t; cp(s3); ct(pt); }
		else if (typ == 13) { --s; cp(s3); ct(pt); cs(ts); }
		else if (typ == 14) { --t; cp(s3); cs(ps); ct(st); }
	}
	cout << ans << "\n";
}

signed main() {
	ios::sync_with_stdio(0); cin.tie(0);
	int tc;
	cin >> tc;
	while (tc--) solve();
}
